  OtpDeliveryProvider,
  SendOtpCommand,
  SendOtpResult,
} from './otp-delivery.provider';

@Injectable()
export class ConsoleOtpDeliveryProvider implements OtpDeliveryProvider {
  private readonly logger = new Logger(ConsoleOtpDeliveryProvider.name);

  constructor(private readonly config: ConfigService) {}

  async sendOtp(command: SendOtpCommand): Promise<SendOtpResult> {
    if (this.config.get<boolean>('OTP_LOG_CODES')) {
      this.logger.debug(
        `[LOCAL SMS OTP] ${command.phone.replace(/^(\d{1})\d+(\d{4})$/, '$1******$2')}: ${command.code}`,
      );
    }

    return { provider: 'console', accepted: true };
  }
}

export type SmsRuErrorCategory =
  | 'INVALID_RECIPIENT'
  | 'RATE_LIMITED'
  | 'PROVIDER_AUTH_ERROR'
  | 'PROVIDER_CONFIGURATION_ERROR'
  | 'PROVIDER_BALANCE_ERROR'
  | 'PROVIDER_TEMPORARILY_UNAVAILABLE'
  | 'MESSAGE_REJECTED'
  | 'UNKNOWN_PROVIDER_ERROR';

export type SmsRuResponse = {
  status?: string;
  status_code?: number;
  balance?: number;
  sms?: Record<
