    private readonly deliveryProvider: OtpDeliveryProvider,
  ) {}

  async sendOtp(dto: SendOtpDto, clientIp?: string) {
    const { value: login, type } = this.parseLogin(this.required(dto.login, 'login'));
    const purpose = this.parseMode(dto.mode);
    const now = new Date();
    const ttlSeconds = this.config.getOrThrow<number>('OTP_CODE_TTL_SECONDS');
    const code = randomInt(0, 1_000_000).toString().padStart(6, '0');
    const id = randomUUID();
    const codeHash = this.hash(`${id}:${login}:${purpose}:${code}`);
    const ipHash = clientIp ? this.hash(`ip:${clientIp}`) : undefined;

    await this.prisma.$transaction(async (tx) => {
      await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${`otp:${login}`}))`;
      if (ipHash) {
        await tx.$executeRaw`SELECT pg_advisory_xact_lock(hashtext(${`otp:${ipHash}`}))`;
      }

      const cooldown = this.config.getOrThrow<number>('OTP_RESEND_COOLDOWN_SECONDS');
      const last = await tx.otpCode.findFirst({
        where: { login, sentAt: { not: null } },
        orderBy: { sentAt: 'desc' },
        select: { sentAt: true },
      });
      if (last.sentAt && last.sentAt.getTime() > now.getTime() - cooldown * 1000) {
        throw new TooManyRequestsException('Please wait before requesting another code');
      }

      const since = new Date(now.getTime() - 60 * 60 * 1000);
      const [phoneCount, ipCount] = await Promise.all([
        tx.otpCode.count({ where: { login, sentAt: { gte: since } } }),
        ipHash
          ? tx.otpCode.count({ where: { clientIpHash: ipHash, sentAt: { gte: since } } })
          : Promise.resolve(0),
      ]);
      if (
        phoneCount >= this.config.getOrThrow<number>('OTP_MAX_SENDS_PER_PHONE_PER_HOUR') ||
        (ipHash && ipCount >= this.config.getOrThrow<number>('OTP_MAX_SENDS_PER_IP_PER_HOUR'))
      ) {
        throw new TooManyRequestsException('OTP request limit exceeded');
      }

      let delivery: {
        provider: string;
        externalMessageId?: string;
        providerStatusCode?: number;
      };
      try {
        if (type === 'phone') {
          delivery = await this.deliveryProvider.sendOtp({
            phone: login,
            code,
            clientIp,
            expiresInSeconds: ttlSeconds,
          });
        } else {
          await this.notificationService.sendOtpCode('email', login, code);
          delivery = { provider: 'email' };
        }
      } catch (error) {
        this.mapDeliveryError(error);
      }

      await tx.otpCode.create({
        data: {
          id,
          login,
          type,
          purpose,
          codeHash,
          expiresAt: new Date(now.getTime() + ttlSeconds * 1000),
          provider: delivery!.provider,
          providerMessageId: delivery!.externalMessageId,
          providerStatusCode: delivery!.providerStatusCode,
          deliveryStatus: 'ACCEPTED',
          sentAt: now,
          clientIpHash: ipHash,
        },
      });

      const active = await tx.otpCode.findMany({
        where: { login, consumedAt: null, expiresAt: { gt: now } },
        orderBy: { createdAt: 'desc' },
        skip: 3,
        select: { id: true },
      });
      if (active.length) {
