            where: { id: latest.id },
            data: { verifyAttempts: { increment: 1 } },
          });
        }
        throw new UnauthorizedException('Invalid or expired OTP code');
      }
      const consumed = await tx.otpCode.updateMany({
        where: { id: matched.id, consumedAt: null, verifyAttempts: { lt: maxAttempts } },
        data: { consumedAt: now },
      });
      if (consumed.count !== 1) throw new UnauthorizedException('Invalid or expired OTP code');
      return matched;
    });

    const existingUser = await this.usersService.findByLogin(login);
    if (purpose === 'register') {
      if (existingUser) throw new UnauthorizedException('Unable to complete authentication');
      const nickname = this.required(dto.nickname, 'nickname');
      const user = await this.usersService.createRegisteredUser({
        email: record.type === 'email' ? login : undefined,
        phone: record.type === 'phone' ? login : undefined,
        nickname,
        inviterReferralCode: this.optional(dto.inviterReferralCode),
      });
      return this.authResponse(user);
    }
    if (!existingUser) throw new UnauthorizedException('Unable to complete authentication');
    return this.authResponse(existingUser);
  }

  private parseLogin(value: string) {
    const normalized = value.trim().toLowerCase();
    if (normalized.includes('@')) {
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized)) throw new BadRequestException('login is invalid');
      return { type: 'email' as const, value: normalized };
    }
    const digits = normalized.replace(/\D/g, '');
    const phone = digits.length === 11 && digits.startsWith('8')
      ? `7${digits.slice(1)}`
      : digits.length === 10
        ? `7${digits}`
        : digits;
    if (!/^7\d{10}$/.test(phone)) throw new BadRequestException('login is invalid');
    return { type: 'phone' as const, value: phone };
  }

  private parseMode(mode: unknown): 'login' | 'register' {
    if (mode !== 'login' && mode !== 'register') throw new BadRequestException('Invalid OTP mode');
    return mode;
  }

  private mapDeliveryError(error: unknown): never {
    if (error instanceof HttpException) throw error;
    if (error instanceof SmsRuError) {
      if (error.category === 'RATE_LIMITED') throw new TooManyRequestsException('SMS sending limit reached');
      if (error.category === 'INVALID_RECIPIENT' || error.category === 'MESSAGE_REJECTED') {
        throw new BadRequestException('Unable to send code to this phone');
      }
    }
    throw new ServiceUnavailableException('Code delivery is temporarily unavailable');
  }

  private hash(value: string) {
    return createHmac('sha256', this.config.getOrThrow<string>('OTP_HASH_SECRET')).update(value).digest('hex');
  }

  private safeEqual(left: string, right: string) {
    const a = Buffer.from(left, 'hex');
    const b = Buffer.from(right, 'hex');
    return a.length === b.length && timingSafeEqual(a, b);
  }

  private authResponse(user: any) {
    return { user, accessToken: this.tokenService.signAccessToken({ sub: user.id, email: user.email ?? '', role: user.role }) };
  }

  private required(value: unknown, field: string) {
    if (typeof value !== 'string' || !value.trim()) throw new BadRequestException(`${field} is required`);
    return value.trim();
  }

  private optional(value: unknown) {
    return typeof value === 'string' && value.trim() ? value.trim() : undefined;
  }
}

