import { Injectable } from '@nestjs/common';

import { PrismaService } from '../prisma/prisma.service';

@Injectable()
export class AdminDashboardService {
  constructor(private readonly prismaService: PrismaService) {}

  async getOverview() {
    const [
      usersCount,
      marketCategoriesCount,
      productsCount,
      collectionsCount,
      ordersCount,
      adCategoriesCount,
      adsCount,
    ] = await this.prismaService.$transaction([
      this.prismaService.user.count({ where: { deletedAt: null } }),
      this.prismaService.marketCategory.count({ where: { deletedAt: null } }),
      this.prismaService.product.count({ where: { deletedAt: null } }),
      this.prismaService.catalogCollection.count(),
      this.prismaService.order.count(),
      this.prismaService.adCategory.count({ where: { deletedAt: null } }),
      this.prismaService.ad.count({ where: { deletedAt: null } }),
    ]);

    return {
      usersCount,
      marketCategoriesCount,
      productsCount,
      collectionsCount,
      ordersCount,
      adCategoriesCount,
      adsCount,
    };
  }

  async getReferrals(): Promise<object[]> {
    const users = await this.prismaService.user.findMany({
      where: { deletedAt: null },
      select: {
        id: true,
        nickname: true,
        nicknameSuffix: true,
        email: true,
        phone: true,
        role: true,
        referralCode: true,
        createdAt: true,
        receivedReferral: { select: { inviterUserId: true } },
        invitedReferrals: {
          select: {
            createdAt: true,
            invited: {
              select: {
                id: true,
                nickname: true,
                nicknameSuffix: true,
                email: true,
                deletedAt: true,
              },
            },
          },
          orderBy: { createdAt: 'asc' },
        },
      },
      orderBy: { createdAt: 'asc' },
    });

    type FlatUser = (typeof users)[number];
    type TreeNode = {
      id: string;
      nickname: string;
      nicknameSuffix?: string;
      email: string | null;
      phone: string | null;
      role: string;
      referralCode: string | null;
      createdAt: Date;
      deletedAt: null;
      invitedBy: string | null;
      directReferralsCount: number;
      directReferrals: TreeNode[];
    };

    const byId = new Map<string, FlatUser>(users.map((user) => [user.id, user]));

    function buildNode(
      user: FlatUser,
      inviterChain: string | null,
      visited: Set<string>,
    ): TreeNode {
      const children = user.invitedReferrals
        .filter((referral) => !visited.has(referral.invited.id))
        .map((referral) => {
          const childUser = byId.get(referral.invited.id);

          if (!childUser) {
            return null;
          }

          const nextVisited = new Set(visited);
          nextVisited.add(referral.invited.id);

          return buildNode(
            childUser,
            inviterChain
              ? `${inviterChain} → ${user.nickname}`.trim()
              : user.nickname.trim() || user.email || user.phone,
            nextVisited,
          );
        })
        .filter((node): node is TreeNode => node !== null);

      return {
        id: user.id,
        nickname: user.nickname,
        nicknameSuffix: user.nicknameSuffix,
        email: user.email,
        phone: user.phone,
        role: user.role,
        referralCode: user.referralCode,
        createdAt: user.createdAt,
        deletedAt: null,
        invitedBy: inviterChain,
        directReferralsCount: children.length,
        directReferrals: children,
      };
    }

    return users
      .filter((user) => !user.receivedReferral)
      .map((user) => buildNode(user, null, new Set([user.id])));
  }
}

import { BadRequestException, Injectable } from '@nestjs/common';
import { CatalogCollectionType } from '@prisma/client';

import { PrismaService } from '../prisma/prisma.service';

const CYRILLIC_MAP: Record<string, string> = {
  а: 'a',
  б: 'b',
  в: 'v',
  г: 'g',
  д: 'd',
  е: 'e',
  ё: 'e',
  ж: 'zh',
  з: 'z',
  и: 'i',
  й: 'y',
  к: 'k',
  л: 'l',
  м: 'm',
  н: 'n',
  о: 'o',
  п: 'p',
  р: 'r',
  с: 's',
  т: 't',
  у: 'u',
  ф: 'f',
  х: 'h',
  ц: 'c',
  ч: 'ch',
  ш: 'sh',
  щ: 'sch',
  ъ: '',
  ы: 'y',
  ь: '',
  э: 'e',
  ю: 'yu',
  я: 'ya',
};

type SlugEntity =
  | 'marketCategory'
  | 'product'
  | 'collection'
  | 'adCategory'
  | 'ad';

@Injectable()
export class AdminInputService {
  constructor(private readonly prismaService: PrismaService) {}

  getObjectBody(body: unknown) {
    return body && typeof body === 'object'
      ? (body as Record<string, unknown>)
      : {};
  }

  getRequiredString(value: unknown, message: string) {
    const result = this.getOptionalString(value);

    if (!result) {
      throw new BadRequestException(message);
    }

    return result;
  }

  getOptionalString(value: unknown) {
    if (typeof value !== 'string') {
      return undefined;
    }

    const trimmedValue = value.trim();

    return trimmedValue || undefined;
  }

  getNumber(value: unknown, fallback: number) {
    if (typeof value === 'number' && Number.isFinite(value)) {
      return value;
    }

    if (typeof value === 'string' && value.trim()) {
      const parsedValue = Number(value);

      if (Number.isFinite(parsedValue)) {
        return parsedValue;
      }
    }

    return fallback;
  }

  getBoolean(value: unknown, fallback: boolean) {
    return typeof value === 'boolean' ? value : fallback;
  }

  getCollectionType(value: unknown) {
    return value === CatalogCollectionType.PRODUCT
      ? CatalogCollectionType.PRODUCT
      : CatalogCollectionType.CATEGORY;
  }

  getImageUrls(payload: Record<string, unknown>) {
    if (Array.isArray(payload.imageUrls)) {
      return payload.imageUrls
        .map((value) => this.getOptionalString(value))
        .filter(Boolean) as string[];
    }

    const imageUrlsText = this.getOptionalString(payload.imageUrls);

    return imageUrlsText
      ? imageUrlsText
          .split('\n')
          .map((value) => value.trim())
          .filter(Boolean)
      : [];
  }

  getIdsFromBody(body: unknown): string[] {
    const payload = this.getObjectBody(body);

    if (!Array.isArray(payload.ids)) {
      throw new BadRequestException('ids must be an array of strings');
    }

    const ids = payload.ids.filter((id) => typeof id === 'string' && id.trim());

    if (!ids.length) {
      throw new BadRequestException('ids array must not be empty');
    }

    return ids as string[];
  }

  async getUniqueSlug(params: {
    entity: SlugEntity;
    value: unknown;
    fallback: string;
    exceptId?: string;
  }) {
    const baseSlug = this.slugify(
      this.getOptionalString(params.value) ?? params.fallback,
    );
    let slug = baseSlug;
    let counter = 1;

    while (await this.isSlugBusy(params.entity, slug, params.exceptId)) {
      slug = `${baseSlug}-${counter}`;
      counter += 1;
    }

    return slug;
  }

  private async isSlugBusy(entity: SlugEntity, slug: string, exceptId?: string) {
    const id = exceptId ? { not: exceptId } : undefined;

    if (entity === 'marketCategory') {
      return Boolean(
        await this.prismaService.marketCategory.findFirst({
          where: { slug, deletedAt: null, id },
        }),
      );
    }

    if (entity === 'product') {
      return Boolean(
        await this.prismaService.product.findFirst({
          where: { slug, deletedAt: null, id },
        }),
      );
    }

    if (entity === 'adCategory') {
      return Boolean(
        await this.prismaService.adCategory.findFirst({
          where: { slug, deletedAt: null, id },
        }),
      );
    }

    if (entity === 'ad') {
      return Boolean(
        await this.prismaService.ad.findFirst({
          where: { slug, deletedAt: null, id },
        }),
      );
    }

    return Boolean(
      await this.prismaService.catalogCollection.findFirst({
        where: { slug, id },
      }),
    );
  }

  private slugify(value: string) {
    const transliteratedValue = value
      .toLowerCase()
      .split('')
      .map((char) => CYRILLIC_MAP[char] ?? char)
      .join('');

    return (
      transliteratedValue
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)+/g, '') || 'item'
    );
  }
}

import { BadRequestException, Inject, Injectable } from '@nestjs/common';
import { randomUUID } from 'node:crypto';

import { FILE_STORAGE, type FileStorage } from '../storage/file-storage';

export type AdminUploadedImageFile = {
  originalname: string;
  mimetype: string;
  size: number;
  buffer?: Buffer;
};

const MAX_IMAGE_UPLOAD_SIZE = 5 * 1024 * 1024;

const IMAGE_MIME_EXTENSION: Record<string, string> = {
  'image/jpeg': '.jpg',
  'image/png': '.png',
  'image/webp': '.webp',
  'image/gif': '.gif',
  'image/avif': '.avif',
};

@Injectable()
export class AdminUploadsService {
  constructor(@Inject(FILE_STORAGE) private readonly fileStorage: FileStorage) {}

  async uploadImage(file?: AdminUploadedImageFile) {
    if (!file?.buffer) {
      throw new BadRequestException('Image file is required');
    }

    const extension = IMAGE_MIME_EXTENSION[file.mimetype];

    if (!extension) {
      throw new BadRequestException('Unsupported image file type');
    }

    if (file.size > MAX_IMAGE_UPLOAD_SIZE) {
      throw new BadRequestException('Image file is too large');
    }

    const fileName = `${randomUUID()}${extension}`;
    const storedFile = await this.fileStorage.upload({
      key: `images/${fileName}`,
      body: file.buffer,
      contentType: file.mimetype,
    });

    return {
      url: storedFile.url,
      fileName,
    };
  }
}

import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { UserRole } from '@prisma/client';

import { PrismaService } from '../prisma/prisma.service';
import { UsersService } from '../users/users.service';

@Injectable()
export class AdminUsersService {
  constructor(
    private readonly prismaService: PrismaService,
    private readonly usersService: UsersService,
  ) {}

  async updateUserRole(id: string, body: unknown) {
    await this.getUserOrThrow(id);
    const payload = this.getObjectBody(body);

    if (
      typeof payload.role !== 'string' ||
      !Object.values(UserRole).includes(payload.role as UserRole)
    ) {
      throw new BadRequestException('Invalid user role');
    }

    await this.prismaService.user.update({
      where: { id },
      data: { role: payload.role as UserRole },
    });

    return this.getAdminUserById(id);
  }

  async deleteUser(id: string) {
    await this.getUserOrThrow(id);
    await this.usersService.softDeleteById(id);

    return this.getAdminUserById(id);
  }

  async hardDeleteUser(id: string) {
    await this.prismaService.$transaction(async (tx) => {
      const adIds = (
        await tx.ad.findMany({ where: { sellerId: id }, select: { id: true } })
      ).map((ad) => ad.id);
      const referralIds = (
        await tx.referral.findMany({
          where: { OR: [{ inviterUserId: id }, { invitedUserId: id }] },
          select: { id: true },
        })
      ).map((referral) => referral.id);

      await tx.referralReward.deleteMany({ where: { referralId: { in: referralIds } } });
      await tx.referral.deleteMany({ where: { id: { in: referralIds } } });
      await tx.cartItem.deleteMany({ where: { OR: [{ userId: id }, { adId: { in: adIds } }] } });
      await tx.favourite.deleteMany({ where: { OR: [{ userId: id }, { adId: { in: adIds } }] } });
      await tx.adImage.deleteMany({ where: { adId: { in: adIds } } });
      await tx.ad.deleteMany({ where: { sellerId: id } });
      await tx.balance.deleteMany({ where: { userId: id } });
      await tx.user.delete({ where: { id } });
    });

    return { deleted: 1 };
  }

  async bulkDeleteUsers(body: unknown) {
    const ids = this.getIdsFromBody(body);
    await Promise.all(ids.map((id) => this.usersService.softDeleteById(id)));

    return { deleted: ids.length };
  }

  async bulkHardDeleteUsers(body: unknown) {
    const ids = this.getIdsFromBody(body);

    await this.prismaService.$transaction(async (tx) => {
      const adIds = (
        await tx.ad.findMany({
          where: { sellerId: { in: ids } },
          select: { id: true },
        })
      ).map((ad) => ad.id);
      const referralIds = (
        await tx.referral.findMany({
          where: {
            OR: [
              { inviterUserId: { in: ids } },
              { invitedUserId: { in: ids } },
            ],
          },
          select: { id: true },
        })
      ).map((referral) => referral.id);

      await tx.referralReward.deleteMany({ where: { referralId: { in: referralIds } } });
      await tx.referral.deleteMany({ where: { id: { in: referralIds } } });
      await tx.cartItem.deleteMany({ where: { OR: [{ userId: { in: ids } }, { adId: { in: adIds } }] } });
      await tx.favourite.deleteMany({ where: { OR: [{ userId: { in: ids } }, { adId: { in: adIds } }] } });
      await tx.adImage.deleteMany({ where: { adId: { in: adIds } } });
      await tx.ad.deleteMany({ where: { sellerId: { in: ids } } });
      await tx.balance.deleteMany({ where: { userId: { in: ids } } });
      await tx.user.deleteMany({ where: { id: { in: ids } } });
    });

    return { deleted: ids.length };
  }

  private getObjectBody(body: unknown) {
    return body && typeof body === 'object'
      ? (body as Record<string, unknown>)
      : {};
  }

  private getIdsFromBody(body: unknown): string[] {
    const payload = this.getObjectBody(body);

    if (!Array.isArray(payload.ids)) {
      throw new BadRequestException('ids must be an array of strings');
    }

    const ids = payload.ids.filter((id) => typeof id === 'string' && id.trim());

    if (!ids.length) {
      throw new BadRequestException('ids array must not be empty');
    }

    return ids as string[];
  }

  private async getUserOrThrow(id: string) {
    const user = await this.prismaService.user.findUnique({ where: { id } });

    if (!user) {
      throw new NotFoundException('User not found');
    }

    return user;
  }

  private async getAdminUserById(id: string) {
    const user = await this.prismaService.user.findUnique({
      where: { id },
      include: {
        avatar: true,
        _count: { select: { ads: true, orders: true } },
      },
    });

    if (!user) {
      throw new NotFoundException('User not found');
    }

    return {
      id: user.id,
      email: user.email,
      nickname: user.nickname,
      nicknameSuffix: user.nicknameSuffix,
      firstName: user.firstName ?? undefined,
      lastName: user.lastName ?? undefined,
      patronymic: user.patronymic ?? undefined,
      role: user.role,
      phone: user.phone ?? undefined,
      referralCode: user.referralCode ?? undefined,
      avatar: user.avatar ?? undefined,
      isActive: user.deletedAt === null,
      deletedAt: user.deletedAt,
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
      adsCount: user._count.ads,
      ordersCount: user._count.orders,
    };
  }
}

