import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';

import { OrderStatus } from '@prisma/client';

import { PrismaService } from '../prisma/prisma.service';
import {
  resolveSelectedProductAdditions,
  type SelectedProductAddition,
} from '../products/product-additions';

import type { CreateOrderDto, CreateOrderItemDto } from './dto/create-order.dto';

type NormalizedOrderItem = {
  productId: string;
  quantity: number;
  selectedAdditions: SelectedProductAddition[];
};

@Injectable()
export class OrdersService {
  constructor(private readonly prismaService: PrismaService) { }

  async create(createOrderDto: CreateOrderDto, userId?: string) {
    const customerName = this.getRequiredString(
      createOrderDto.customerName,
      'customerName',
    );

    const customerPhone = this.getRequiredString(
      createOrderDto.customerPhone,
      'customerPhone',
    );

    const deliveryAddress = this.getRequiredString(
      createOrderDto.deliveryAddress,
      'deliveryAddress',
    );

    const customerEmail = this.getOptionalString(createOrderDto.customerEmail);
    const comment = this.getOptionalString(createOrderDto.comment);
    const guestSessionId = this.getOptionalString(createOrderDto.guestSessionId);

    const normalizedItems = this.getNormalizedItems(createOrderDto.items);
    const productIds = Array.from(
      new Set(normalizedItems.map((item) => item.productId)),
    );

    const products = await this.prismaService.product.findMany({
      where: {
        id: {
          in: productIds,
        },
      },
      select: {
        id: true,
        price: true,
        additions: true,
      },
    });

    if (products.length !== productIds.length) {
      const foundProductIds = new Set(products.map((product) => product.id));

      const missingProductIds = productIds.filter(
        (productId) => !foundProductIds.has(productId),
      );

      throw new BadRequestException(
        `Products not found: ${missingProductIds.join(', ')}`,
      );
    }

    const productById = new Map(
      products.map((product) => [product.id, product]),
    );

    const orderItems = normalizedItems.map((item) => {
      const product = productById.get(item.productId);

      if (!product) {
        throw new BadRequestException(`Product not found: ${item.productId}`);
      }

      const resolved = resolveSelectedProductAdditions(
        product.additions,
        item.selectedAdditions,
      );
      return {
        productId: item.productId,
        quantity: item.quantity,
        baseUnitPrice: product.price,
        unitPrice: product.price + resolved.additionsTotal,
        selectedAdditions: resolved.snapshot,
      };
    });

    const totalAmount = orderItems.reduce(
      (sum, item) => sum + item.unitPrice * item.quantity,
      0,
    );

    const order = await this.prismaService.order.create({
      data: {
        userId,
        guestSessionId,
        customerName,
        customerPhone,
        customerEmail,
        deliveryAddress,
        comment,
        status: OrderStatus.AWAITING_PAYMENT,
        totalAmount,
        items: {
          create: orderItems.map((item) => ({
            product: {
              connect: {
                id: item.productId,
              },
            },
            quantity: item.quantity,
            baseUnitPrice: item.baseUnitPrice,
            unitPrice: item.unitPrice,
            selectedAdditions: item.selectedAdditions,
          })),
        },
      },
      include: this.getOrderInclude(),
    });

    return this.mapOrder(order);
  }

  async findMyOrders(userId: string) {
    const orders = await this.prismaService.order.findMany({
      where: {
        userId,
      },
      include: this.getOrderInclude(),
      orderBy: {
        createdAt: 'desc',
      },
    });

    return orders.map((order) => this.mapOrder(order));
  }

  async findById(orderId: string) {
    const order = await this.prismaService.order.findUnique({
      where: {
        id: orderId,
      },
      include: this.getOrderInclude(),
    });

    if (!order) {
      throw new NotFoundException('Order not found');
    }

    return this.mapOrder(order);
  }

  private getOrderInclude() {
    return {
      items: {
        include: {
          product: {
            include: {
              category: {
                include: {
                  image: true,
                },
              },
              images: {
                include: {
                  image: true,
                },
              },
            },
          },
        },
      },
    };
  }

  private getRequiredString(value: unknown, fieldName: string) {
    if (typeof value !== 'string' || !value.trim()) {
      throw new BadRequestException(`${fieldName} is required`);
    }

    return value.trim();
  }

  private getOptionalString(value: unknown) {
    if (typeof value !== 'string') {
      return undefined;
    }

    const normalizedValue = value.trim();

    return normalizedValue || undefined;
  }

  private getNormalizedItems(items?: CreateOrderItemDto[]) {
    if (!Array.isArray(items) || !items.length) {
      throw new BadRequestException('items are required');
    }

    const itemByConfiguration = new Map<string, NormalizedOrderItem>();

    items.forEach((item) => {
      if (!item?.productId) {
        throw new BadRequestException('productId is required');
      }

      const quantity = Number(item.quantity);

      if (!Number.isInteger(quantity) || quantity < 1) {
        throw new BadRequestException('quantity must be a positive integer');
      }

      const selectedAdditions = Array.isArray(item.selectedAdditions)
        ? item.selectedAdditions
        : [];
      const canonicalSelection = [...selectedAdditions].sort((first, second) =>
        first.additionId.localeCompare(second.additionId),
      );
      const key = `${item.productId}:${JSON.stringify(canonicalSelection)}`;
      const current = itemByConfiguration.get(key);
      itemByConfiguration.set(key, {
        productId: item.productId,
        quantity: (current?.quantity ?? 0) + quantity,
        selectedAdditions: canonicalSelection,
      });
    });

    return Array.from(itemByConfiguration.values());
  }

  private mapOrder(order: any) {
    return {
      id: order.id,
      userId: order.userId ?? undefined,
      guestSessionId: order.guestSessionId ?? undefined,
      customerName: order.customerName,
      customerPhone: order.customerPhone,
      customerEmail: order.customerEmail ?? undefined,
      deliveryAddress: order.deliveryAddress,
      comment: order.comment ?? undefined,
      status: order.status,
      totalAmount: order.totalAmount,
      createdAt: order.createdAt,
      updatedAt: order.updatedAt,
      items: order.items.map((item: any) => ({
        id: item.id,
        productId: item.productId,
        quantity: item.quantity,
        baseUnitPrice: item.baseUnitPrice,
        unitPrice: item.unitPrice,
        selectedAdditions: item.selectedAdditions ?? [],
        product: item.product ? this.mapOrderProduct(item.product) : undefined,
      })),
    };
  }

  private mapOrderProduct(product: any) {
    return {
      id: product.id,
      categoryId: product.categoryId,
      category: {
        id: product.category.id,
        name: product.category.name,
        slug: product.category.slug,
        path: product.category.slug,
        sortOrder: product.category.sortOrder,
        description: product.category.description ?? undefined,
        parentId: product.category.parentId ?? undefined,
        image: product.category.image ?? undefined,
      },
      title: product.title,
      slug: product.slug,
      description: product.description,
      price: product.price,
      additions: product.additions ?? [],
      createdAt: product.createdAt,
      updatedAt: product.updatedAt,
      images: product.images
        .map((productImage: any) => productImage.image)
        .sort(
          (firstImage: any, secondImage: any) =>
            firstImage.sortOrder - secondImage.sortOrder,
        ),
    };
  }
}

import {
  BadRequestException,
  Body,
  Controller,
  Headers,
  NotFoundException,
  Param,
  Post,
} from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { ApiTags } from '@nestjs/swagger';

import { OrderStatus } from '@prisma/client';

import { AuthService } from '../auth/auth.service';
import { PrismaService } from '../prisma/prisma.service';

import { PaymentsService } from './payments.service';
import type { YookassaWebhookPayload } from './types/yookassa.types';

@ApiTags('Payments')
@Controller()
export class PaymentsController {
  constructor(
    private readonly paymentsService: PaymentsService,
    private readonly prismaService: PrismaService,
    private readonly authService: AuthService,
    private readonly configService: ConfigService,
  ) {}

  @Post('orders/:orderId/payment')
  async createPayment(
    @Param('orderId') orderId: string,
    @Headers('authorization') authorizationHeader?: string,
  ) {
    const user = await this.authService.getOptionalMeFromAuthorizationHeader(
      authorizationHeader,
    );

    const order = await this.prismaService.order.findUnique({
      where: { id: orderId },
    });

    if (!order) {
      throw new NotFoundException('Order not found');
    }

    if (user && order.userId && order.userId !== user.id) {
      throw new BadRequestException('Access denied');
    }

    if (order.status !== OrderStatus.AWAITING_PAYMENT) {
      throw new BadRequestException(
        `Cannot initiate payment for order with status ${order.status}`,
      );
    }

    const webAppUrl = this.configService.getOrThrow<string>('WEB_APP_URL');
    const returnUrl = `${webAppUrl}/checkout/result?orderId=${orderId}`;

    const payment = await this.paymentsService.createPayment({
      orderId: order.id,
      amountKopecks: order.totalAmount,
      description: `Заказ №${order.id.slice(0, 8)}`,
      returnUrl,
    });

    await this.prismaService.order.update({
      where: { id: orderId },
      data: { yookassaPaymentId: payment.id },
    });

    const confirmation = payment.confirmation as { type: string; confirmation_token?: string };

    return {
      paymentId: payment.id,
      confirmationToken: confirmation.confirmation_token ?? null,
      status: payment.status,
    };
  }

  @Post('payments/webhook')
  async handleWebhook(@Body() body: unknown) {
    let payload: YookassaWebhookPayload;

    try {
      payload = this.paymentsService.parseWebhook(body);
    } catch {
      throw new BadRequestException('Invalid webhook payload');
    }

    const yookassaPaymentId = payload.object.id;

    const order = await this.prismaService.order.findFirst({
      where: { yookassaPaymentId },
    });

    if (!order) {
      return { received: true };
    }

    if (payload.event === 'payment.succeeded') {
      await this.prismaService.order.update({
        where: { id: order.id },
        data: { status: OrderStatus.PAID },
      });
    } else if (payload.event === 'payment.canceled') {
      await this.prismaService.order.update({
        where: { id: order.id },
        data: { status: OrderStatus.CANCELLED },
      });
    }

    return { received: true };
  }
}

import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { randomUUID } from 'node:crypto';

import type { YookassaPayment, YookassaWebhookPayload } from './types/yookassa.types';

@Injectable()
export class PaymentsService {
  private readonly baseUrl = 'https://api.yookassa.ru/v3';

  constructor(private readonly configService: ConfigService) {}

  private getAuthHeader(): string {
    const shopId = this.configService.get<string>('YOOKASSA_SHOP_ID');
    const secretKey = this.configService.get<string>('YOOKASSA_SECRET_KEY');

    if (!shopId || !secretKey) {
      throw new InternalServerErrorException(
        'YOOKASSA_SHOP_ID or YOOKASSA_SECRET_KEY is not configured',
      );
    }

    return `Basic ${Buffer.from(`${shopId}:${secretKey}`).toString('base64')}`;
  }

  async createPayment(params: {
    orderId: string;
    amountKopecks: number;
    description: string;
    returnUrl: string;
  }): Promise<YookassaPayment> {
    const amountRubles = (params.amountKopecks / 100).toFixed(2);

    const response = await fetch(`${this.baseUrl}/payments`, {
      method: 'POST',
      headers: {
        Authorization: this.getAuthHeader(),
        'Idempotence-Key': randomUUID(),
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        amount: {
          value: amountRubles,
          currency: 'RUB',
        },
        confirmation: {
          type: 'embedded',
        },
        description: params.description,
        metadata: {
          orderId: params.orderId,
        },
        capture: true,
      }),
    });

    if (!response.ok) {
      const error = await response.text();
      throw new InternalServerErrorException(
        `YooKassa createPayment failed: ${error}`,
      );
    }

    return response.json() as Promise<YookassaPayment>;
  }

  async getPayment(paymentId: string): Promise<YookassaPayment> {
    const response = await fetch(`${this.baseUrl}/payments/${paymentId}`, {
      headers: {
        Authorization: this.getAuthHeader(),
      },
    });

    if (!response.ok) {
      const error = await response.text();
      throw new InternalServerErrorException(
        `YooKassa getPayment failed: ${error}`,
      );
    }

    return response.json() as Promise<YookassaPayment>;
  }

  parseWebhook(body: unknown): YookassaWebhookPayload {
    const payload = body as YookassaWebhookPayload;

    if (payload?.type !== 'notification' || !payload?.event || !payload?.object?.id) {
      throw new Error('Invalid webhook payload');
    }

    return payload;
  }
}

